// Splicer no longer needs cross-origin isolation. Returning visitors still have
// the old coi-serviceworker registered at this URL; the browser's update check
// fetches this stub, which removes the registration without reloading any page.
self.addEventListener('install', () => self.skipWaiting())
self.addEventListener('activate', (event) => {
  event.waitUntil(self.registration.unregister())
})
